#!/usr/bin/env bash
# Generated by Copilot

set -euo pipefail

usage() {
  cat <<'EOF'
Usage: scripts/fix-audio.sh <mp3-file>

Runs ffprobe to detect "invalid concatenated file" warnings and, if found,
rewrites the MP3 headers with ffmpeg to regenerate a proper Xing/LAME header.
The fixed file is written alongside the original with a *_fixed.mp3 suffix.
EOF
}

if [[ ${1-} == "" ]]; then
  usage >&2
  exit 1
fi

INPUT_FILE=$1
if [[ ! -f "$INPUT_FILE" ]]; then
  echo "Error: file not found: $INPUT_FILE" >&2
  exit 1
fi

if ! command -v ffprobe >/dev/null 2>&1; then
  echo "Error: ffprobe is not installed or not on PATH" >&2
  exit 1
fi

if ! command -v ffmpeg >/dev/null 2>&1; then
  echo "Error: ffmpeg is not installed or not on PATH" >&2
  exit 1
fi

run_ffprobe() {
  ffprobe -hide_banner -show_entries format=duration "$1" 2>&1 || true
}

probe_output=$(run_ffprobe "$INPUT_FILE")
echo "$probe_output"

if [[ "$probe_output" != *"invalid concatenated file detected"* ]]; then
  echo "No invalid concatenation detected; nothing to fix." >&2
  exit 0
fi

extension="${INPUT_FILE##*.}"
base_name="${INPUT_FILE%.*}"
if [[ "$base_name" == *_fixed ]]; then
  output_file="${base_name}_rewrapped.${extension}"
else
  output_file="${base_name}_fixed.${extension}"
fi

if [[ -e "$output_file" ]]; then
  echo "Error: output file already exists: $output_file" >&2
  exit 1
fi

echo "Invalid concatenation detected; rewriting to $output_file" >&2
ffmpeg -i "$INPUT_FILE" -c copy -map_metadata -1 -write_xing 1 "$output_file"

probe_fixed=$(run_ffprobe "$output_file")
echo "$probe_fixed"

if [[ "$probe_fixed" == *"invalid concatenated file detected"* ]]; then
  echo "Warning: ffmpeg fix did not remove the invalid concatenation warning." >&2
  exit 2
fi

echo "Fix applied successfully: $output_file" >&2
